[
  {
    "statement": "A study in Israel and off Sweden found that creating hole habitats on subtidal artificial structures increased the abundance of brown crabs.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "A study in Israel and off Sweden found that creating hole habitats on subtidal artificial structures did not increase the abundance of other mobile invertebrates.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "A study reported that creating holes along with pits, grooves and environmentally-sensitive material had mixed effects on invertebrate abundances, depending on the species group.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "A study in Italy found that creating textured surfaces on subtidal artificial structures had mixed effects on the non-mobile invertebrate abundance on structure surfaces, depending on the site.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Studies in Australia and France found that creating short flexible habitats on subtidal artificial structures had mixed effects on the mobile and/or non-mobile invertebrate abundance on and around structure surfaces.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "The effects of creating short flexible habitats on invertebrate abundance depended on the survey week, species group, flexible habitat length, or site.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "One study on creating short flexible habitats on subtidal artificial structures found no effect on mobile invertebrate abundance.",
    "citations": [
      "3450"
    ]
  }
]

[
  {
    "statement": "Nine of twelve replicated, controlled studies found that rock pools created on intertidal artificial structures supported higher combined macroalgae, invertebrate and/or fish species diversity and/or richness than structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Three replicated, controlled studies found that creating hole habitats on intertidal artificial structures, along with rock pools, grooves, small protrusions and environmentally-sensitive material, increased the combined macroalgae and invertebrate species diversity and/or richness on structure surfaces.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "One before-and-after study reported that creating pools, along with reducing the slope of a structure, increased the combined macroalgae, invertebrate and fish species richness on the structure.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Three studies reported similar combined macroalgae and invertebrate or combined mobile invertebrate and fish species richness in pools and on structure surfaces.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "One study found that combined macroalgae, invertebrate and fish species richness in created pools was similar to natural rock pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "One study reported lower combined mobile invertebrate and fish species richness in created pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Created rock pools and holes were found to support macroalgae, mobile invertebrate, non-mobile invertebrate and/or fish species that were absent from structure surfaces without these features.",
    "citations": [
      "3476",
      "3467"
    ]
  },
  {
    "statement": "Two studies found the shore level of pools did not affect species richness.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Three studies found that pool depth had no effect on species richness.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "One study found higher richness in tilted pools than in horizontal ones.",
    "citations": [
      "3476"
    ]
  }
]

[
  {
    "statement": "A replicated, randomized, controlled study in Australia reported that large protrusions created on an intertidal artificial structure supported mobile and non-mobile invertebrate species that were absent from structure surfaces without protrusions.",
    "citations": [
      "3463"
    ]
  },
  {
    "statement": "Two replicated, controlled studies in the UK and Australia found that creating large protrusions on an intertidal artificial structure, along with large ridges in one study, did not increase the combined macroalgae and invertebrate species richness on structure surfaces.",
    "citations": [
      "3463"
    ]
  },
  {
    "statement": "A replicated, controlled study in the UK found that creating large protrusions on an intertidal artificial structure, along with large ridges, increased limpet abundance on structure surfaces.",
    "citations": [
      "3463"
    ]
  },
  {
    "statement": "A replicated, controlled study in the UK found that creating large protrusions on an intertidal artificial structure, along with large ridges, did not increase barnacle abundance on structure surfaces.",
    "citations": [
      "3463"
    ]
  },
  {
    "statement": "One of two replicated, controlled studies in the USA and the UK reported that creating large ledges on intertidal artificial structures, along with grooves and small protrusions, increased the combined macroalgae, microalgae and invertebrate species diversity on structure surfaces.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "One study found that creating large ridges, along with large protrusions, did not increase the combined macroalgae and invertebrate species richness.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "A replicated, randomized, controlled study in the USA reported that creating large ledges on intertidal artificial structures, along with grooves and small protrusions, increased the combined macroalgae, microalgae and invertebrate abundance on structure surfaces.",
    "citations": [
      "3465"
    ]
  }
]

[
  {
    "statement": "Creating groove habitats, small ledges, holes, and using environmentally-sensitive material on a subtidal artificial structure altered the combined macroalgae and invertebrate community composition on the structure's surfaces.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Adding habitat features to subtidal artificial structures supported non-mobile invertebrate species that were absent from structure surfaces without these features.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "A study found that creating grooves and small protrusions had mixed effects on the community composition, with the effects depending on the orientation of the structure's surfaces.",
    "citations": [
      "3452"
    ]
  },
  {
    "statement": "Creating short flexible habitats on subtidal artificial structures had mixed effects on the mobile and/or non-mobile invertebrate community composition.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "The effects of short flexible habitats on the invertebrate community composition depended on the density or length of the flexible habitats and/or the site.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "In one study, the creation of short flexible habitats altered the non-mobile invertebrate community composition.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Reducing the frequency of cleaning on subtidal artificial structures did not alter the combined invertebrate and fish community composition on and around the structure's surfaces.",
    "citations": [
      "3447"
    ]
  }
]

[
  {
    "statement": "A study in an estuary in southeast Australia indicated that creating short flexible habitats on intertidal artificial structures did not lead to an increase in fish abundance.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "The short flexible habitats created were between 1 and 50 mm.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "The lack of an increase in fish abundance was observed on and around the structure surfaces during high tide.",
    "citations": [
      "3459"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects on biodiversity of creating large protrusions (>50 mm) on subtidal artificial structures.",
    "citations": [
      "3443",
      "3445",
      "3444"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on biodiversity of creating large ridges or ledges (>50 mm) on subtidal artificial structures.",
    "citations": [
      "3443",
      "3445",
      "3444"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on biodiversity of creating small ridges or ledges (1–50 mm) on subtidal artificial structures.",
    "citations": [
      "3443",
      "3445",
      "3444"
    ]
  }
]

[
  {
    "statement": "Studies in estuaries in southeast Australia have examined several conservation actions for artificial structures.",
    "citations": []
  },
  {
    "statement": "In one study, reducing the slope of intertidal artificial structures increased the combined macroalgae, invertebrate and fish species richness when combined with creating rock pools.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Another study found that reducing the slope of intertidal artificial structures did not increase macroalgal, oyster or mobile invertebrate abundance.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Creating long flexible habitats (greater than 50 mm) on subtidal artificial structures supported macroalgae, non-mobile invertebrate and fish species that were not present on surfaces without these habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The effects of creating long flexible habitats on fish species richness and the abundance of invertebrates and fish were mixed.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Transplanting oysters onto intertidal artificial structures supported macroalgae, mobile invertebrate, non-mobile invertebrate, and fish species that were absent from surfaces without the oysters.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In one study, transplanting oysters onto intertidal artificial structures increased mobile invertebrate species richness.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Other studies found that transplanting oysters had mixed effects on combined macroalgae and invertebrate species richness and abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Other studies found that transplanting oysters resulted in no increase in fish species richness or abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In one study, the creation of short flexible habitats (1-50 mm) on intertidal artificial structures was found to decrease the combined macroalgae, invertebrate and fish species richness.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "The creation of short flexible habitats on intertidal artificial structures had mixed effects on the abundance of different species.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Creating pit habitats (1-50 mm) on intertidal artificial structures was found to alter the macroalgae and invertebrate community composition.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "In one study that also included grooves, creating pit habitats altered the fish community.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "A study found that creating pit and groove habitats on intertidal artificial structures supported species that were absent from surfaces without these additions.",
    "citations": [
      "3475"
    ]
  }
]

[
  {
    "statement": "Creating grooves and small ridges or ledges (1–50 mm) on intertidal artificial structures has been found to alter the composition of the combined macroalgae and invertebrate community.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Grooves and small ridges or ledges (1–50 mm) on intertidal artificial structures can support species that were not present on surfaces without these features.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Some studies found that creating small grooves, ridges, or ledges on intertidal artificial structures increased the diversity and richness of species.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Other studies found that the effect of small grooves, ridges, or ledges on intertidal artificial structures had mixed effects on species diversity and richness, depending on factors like the site, shore level, and feature size and arrangement.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Some studies showed an increase in the combined macroalgae and invertebrate abundance after adding small grooves, ridges, or ledges to intertidal artificial structures.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Other studies found no increase or mixed effects on the combined macroalgae and invertebrate abundance after adding small grooves, ridges, or ledges to intertidal artificial structures.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "For fish, creating grooves and ledges on intertidal artificial structures did not increase species richness or abundance in most studies.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating grooves and ledges on intertidal artificial structures did increase the time benthic fishes spent interacting with the surfaces.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Some studies found that small ridges or ledges (1–50 mm) on their own did not alter the community composition or increase species richness on intertidal artificial structures.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Small ridges or ledges (1–50 mm) on intertidal artificial structures supported lower species richness and abundance of mobile invertebrates and oysters compared to the grooves between them.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Creating just groove habitats (1–50 mm) on intertidal artificial structures has shown mixed results.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "While some studies found no change in the overall community composition from creating groove habitats, one study noted that grooves supported species not found on unmodified surfaces.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies found that creating groove habitats on intertidal artificial structures led to an increase in overall species richness and diversity, while other studies did not.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Grooves on intertidal artificial structures were found to support higher species richness than the ridges or ledges between the grooves.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "In one study, fish species richness and abundance were found to increase where grooves were added along with pits to intertidal artificial structures.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "One study reported that large ridges or ledges (>50 mm) on intertidal artificial structures increased the diversity of species.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "One study reported that large ridges or ledges (>50 mm) on intertidal artificial structures increased the overall abundance of macroalgae, microalgae, and invertebrates.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Large ridges or ledges (>50 mm) on intertidal artificial structures increased the abundance of certain species like mussels or limpets, but not barnacles.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Large ridges or ledges (>50 mm) on intertidal artificial structures did not increase the abundance of juvenile salmon.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Large ridges or ledges (>50 mm) on intertidal artificial structures did increase the feeding activity of juvenile salmon around the structure.",
    "citations": [
      "3465"
    ]
  }
]

